import React, { useEffect, useState } from "react";
import { NavLink } from "react-router-dom";
import "./Navbar.css";
import bgVideo from "../assets/bkVid.mp4";

const NAV_LINKS = [
  { to: "/", label: "Home" },
  { to: "/about", label: "About" },
  { to: "/products", label: "Products" },
  { to: "/contact", label: "Contact" },
];

function Navbar() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 30);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <nav
      className={`navbar navbar-expand-lg sticky-top honey-navbar ${
        scrolled ? "honey-navbar--scrolled" : ""
      }`}
    >
      {/* 🎥 Background Video */}
      <video
        autoPlay
        loop
        muted
        playsInline
        className="honey-video-bg"
      >
        <source src={bgVideo} type="video/mp4" />
      </video>

      {/* 🌑 Overlay */}
      <div className="honey-video-overlay"></div>

      <div className="container position-relative">

        {/* Brand */}
        <NavLink className="navbar-brand honey-brand" to="/">
          <span className="honey-brand__icon">🍯</span>
          <span className="honey-brand__name">GoldenHive</span>
        </NavLink>

        {/* Mobile Toggle */}
        <button
          className="navbar-toggler"
          type="button"
          data-bs-toggle="collapse"
          data-bs-target="#mainNav"
        >
          <span className="navbar-toggler-icon"></span>
        </button>

        {/* Links */}
        <div className="collapse navbar-collapse" id="mainNav">
          <ul className="navbar-nav ms-auto align-items-lg-center gap-lg-1">

            {NAV_LINKS.map(({ to, label }) => (
              <li className="nav-item" key={to}>
                <NavLink
                  to={to}
                  end={to === "/"}
                  className={({ isActive }) =>
                    `nav-link honey-nav-link ${isActive ? "active" : ""}`
                  }
                >
                  {label}
                </NavLink>
              </li>
            ))}

            {/* CTA */}
            <li className="nav-item ms-lg-3 mt-2 mt-lg-0">
              <NavLink
                to="/products"
                className="btn honey-btn-cta btn-sm"
              >
                Shop Now
              </NavLink>
            </li>

          </ul>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;
